function crossStitchProcess(data,w,h,opts){
  opts=opts||{};
  var cell=opts.cell!=null?opts.cell:12;
  if(cell<4)cell=4; else if(cell>32)cell=32;
  var out=new Uint8ClampedArray(data.length);
  for(var i=0;i<out.length;i+=4){ out[i]=238; out[i+1]=232; out[i+2]=214; out[i+3]=255; }
  for(var gy=0;gy<h;gy+=cell) for(var gx=0;gx<w;gx+=cell){
    var cw=Math.min(cell,w-gx), ch=Math.min(cell,h-gy);
    var sr=0,sg=0,sb=0,n=0;
    for(var yy=gy;yy<gy+ch;yy++) for(var xx=gx;xx<gx+cw;xx++){ var p=(yy*w+xx)*4; sr+=data[p]; sg+=data[p+1]; sb+=data[p+2]; n++; }
    var r=Math.round(sr/n), g=Math.round(sg/n), b=Math.round(sb/n);
    var x0=gx, y0=gy, x1=gx+cw-1, y1=gy+ch-1;
    var th=Math.max(1.2, cell*0.12);
    for(var py=y0;py<=y1;py++) for(var px=x0;px<=x1;px++){
      var e1=Math.abs((py-y0)*(x1-x0)-(px-x0)*(y1-y0));
      var e2=Math.abs((py-y1)*(x1-x0)-(px-x0)*(y0-y1));
      if(e1<=th||e2<=th){ var pp=(py*w+px)*4; out[pp]=r; out[pp+1]=g; out[pp+2]=b; }
    }
  }
  return out;
}

var EXPORTS={crossStitchProcess:crossStitchProcess};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.CrossStitchForgePure = EXPORTS; }
